import {
    VariableSet,
    SingleLineTextVariable,
    MultiLineTextVariable,
    SelectBoxVariable,
    MultipleChoiceVariable,
    CheckboxVariable,
    ReferenceVariable,
    RequestedForVariable,
    MaskedVariable,
    YesNoVariable,
    NumericScaleVariable,
    DateVariable,
    LookupSelectBoxVariable,
    ListCollectorVariable,
    LabelVariable,
    BreakVariable,
    ContainerStartVariable,
    ContainerEndVariable,
    HtmlVariable,
    EmailVariable,
} from '@servicenow/sdk/core'

VariableSet({
    $id: Now.ID['vs_min'],
    title: 'Minimal Set',
})

VariableSet({
    $id: Now.ID['vs_full'],
    title: 'Employee & <Context> Set',
    internalName: 'employee_context',
    name: 'Employee context',
    description: 'Who is asking',
    type: 'singleRow',
    layout: '2across',
    order: 200,
    displayTitle: true,
    setAttributes: 'a=b',
    version: 3,
    readRoles: ['itil', 'admin', 'itil'],
    writeRoles: ['admin'],
    createRoles: [],
    variables: {
        requested_for: RequestedForVariable({ question: 'Requested for', order: 100, mandatory: true }),
        manager: ReferenceVariable({
            question: 'Manager',
            referenceTable: 'sys_user',
            order: 200,
            dependentQuestion: 'requested_for',
            dotWalkPath: 'manager',
            useDynamicDefault: true,
            referenceQualCondition: 'active=true',
        }),
        short: SingleLineTextVariable({
            question: 'Short <text>',
            order: 300,
            tooltip: 'tip',
            exampleText: 'ex',
            helpText: 'help',
            showHelp: true,
            instructions: 'Do <this>',
            width: 50,
            defaultValue: 'x',
            readRoles: ['itil'],
            visibility: 'Bundle',
            pricingDetails: [{ amount: 5, currencyType: 'USD', field: 'price' }],
            description: 'desc',
            global: true,
            unique: true,
        }),
        long: MultiLineTextVariable({ question: 'Long' }),
        size: SelectBoxVariable({
            question: 'Size',
            includeNone: true,
            choices: {
                s: { label: 'Small', sequence: 1 },
                m: { label: 'Medium', sequence: 2, pricingDetails: [{ amount: 2, currencyType: 'EUR', field: 'recurring_price' }] },
                l: { label: 'Large', inactive: true },
            },
        }),
        color: MultipleChoiceVariable({ question: 'Color', choiceDirection: 'across', choices: { red: { label: 'Red' } } }),
        agree: CheckboxVariable({ question: 'Agree', selectionRequired: true }),
        secret: MaskedVariable({ question: 'Secret', useConfirmation: true }),
        plain: MaskedVariable({ question: 'Plain', useEncryption: false }),
        yes: YesNoVariable({ question: 'Yes?' }),
        scale: NumericScaleVariable({ question: 'Scale', scaleMin: 1, scaleMax: 10 }),
        when: DateVariable({ question: 'When' }),
        lookup: LookupSelectBoxVariable({
            question: 'Lookup',
            lookupFromTable: 'cmn_location',
            lookupValueField: 'sys_id',
            lookupLabelFields: ['name', 'city'],
        }),
        list: ListCollectorVariable({ question: 'List', listTable: 'sys_user' }),
        label: LabelVariable({ question: 'Label' }),
        br: BreakVariable({}),
        cs: ContainerStartVariable({ question: 'Box' }),
        ce: ContainerEndVariable({}),
        html: HtmlVariable({ question: 'Html', defaultHTML: '<b>hi</b>' }),
        mail: EmailVariable({ question: 'Mail' }),
    },
})

VariableSet({
    $id: Now.ID['vs_multi'],
    title: 'Multi Row Items',
    type: 'multiRow',
    variables: {
        item: SingleLineTextVariable({ question: 'Item' }),
    },
})
